        )
        self.assertEqual(
            list(GFKCompositeTarget.objects.filter(attachments__isnull=False)),
            [self.t_with],
        )

    def test_json_hostile_components(self):
        hostile = ['quote "x"', "back\\slash", "bracket ] [", 'comma , inside',
                   "new\nline", "tab\there", "{}", "[]", "[1, \"1\"]", "null"]
        for index, tenant in enumerate(hostile, start=100):
            target = GFKCompositeTarget.objects.create(code=index, tenant=tenant)
            GFKCompositeAttachment.objects.create(
                text="h-%d" % index, content_object=target
            )
        for index, tenant in enumerate(hostile, start=100):
            with self.subTest(tenant=tenant):
                self.assertEqual(
                    list(
                        GFKCompositeTarget.objects.filter(
                            attachments__text="h-%d" % index
                        )
                    ),
                    [GFKCompositeTarget.objects.get(code=index, tenant=tenant)],
                )
                source = GFKCompositeAttachment.objects.get(text="h-%d" % index)
                source.refresh_from_db()
                self.assertEqual(source.content_object.pk, (index, tenant))

    def test_corrupt_rows_during_reverse_prefetch(self):
        ct = ContentType.objects.get_for_model(GFKCompositeTarget)
        bad = GFKCompositeAttachment.objects.create(text="bad")
        GFKCompositeAttachment.objects.filter(pk=bad.pk).update(
            content_type=ct, object_id="{corrupt"
        )
        targets = list(
            GFKCompositeTarget.objects.prefetch_related("attachments").order_by("pk")
        )
        by_pk = {t.pk: list(t.attachments.all()) for t in targets}
        self.assertEqual(len(by_pk[(1, "1")]), 1)
        self.assertEqual(by_pk[(2, "2")], [])
        # The corrupt row belongs to no target.
        self.assertNotIn(bad.pk, [s.pk for s in by_pk[(1, "1")]])

